// === SPRINT_1_3_DISTRIBUTED_LOCK ===
// Distributed lock (Sprint 1.3, 2026-05-28) — defensa contra overlap entre ejecuciones
// Si otro cron-run ya tiene el lock, este skip. TTL libera tras crash.
// Fail-OPEN: si Redis down, proceder sin lock (preferimos correr 2x que skip).
const _LOCK_ERP_URL = 'https://erp.livskin.site/api/internal/lock';
const _LOCK_AUDIT_TOKEN = $env.AUDIT_INTERNAL_TOKEN;
if (_LOCK_AUDIT_TOKEN) {
  try {
    const _lockRes = await this.helpers.httpRequest({
      method: 'POST',
      url: _LOCK_ERP_URL + '/acquire',
      headers: { 'X-Internal-Token': _LOCK_AUDIT_TOKEN, 'Content-Type': 'application/json' },
      body: { key: 'cron:f2-auto-close-cold-leads', ttl_seconds: 120 },
      json: true,
      timeout: 5000,
    });
    if (_lockRes && _lockRes.acquired === false) {
      return [{ json: { skipped: true, reason: 'lock_held', lock_key: 'cron:f2-auto-close-cold-leads' } }];
    }
  } catch (_e) {
    console.warn('[lock] acquire failed, proceeding without lock:', _e.message);
  }
}
// === END SPRINT_1_3_DISTRIBUTED_LOCK ===

// ============================================================================
// F2 AUTO-CLOSE COLD LEADS
// Cron diario 04:00 Lima: cierra leads en qualifying con followup_sent=true
// y last_inbound > 72h. Marca state=closed con flag='closed_cold'.
// Resuelve Gap A: leads que NO respondieron al follow-up quedan eternamente.
// ============================================================================

const AUDIT_TOKEN = $env.AUDIT_INTERNAL_TOKEN;
const ERP_BASE = 'https://erp.livskin.site';

if (!AUDIT_TOKEN) return [{ json: { error: 'AUDIT_INTERNAL_TOKEN missing' } }];

// Fetch ALL qualifying leads (no usamos pending-followup porque queremos los ya con followup_sent=true)
// Endpoint nuevo: /api/internal/wa-state/cold-candidates
let candidates;
try {
  candidates = await this.helpers.httpRequest({
    method: 'GET',
    url: ERP_BASE + '/api/internal/wa-state/cold-candidates',
    qs: { hours_since_inbound: 72 },
    headers: { 'X-Internal-Token': AUDIT_TOKEN },
    json: true,
    timeout: 10000,
  });
} catch (e) {
  return [{ json: { error: 'fetch failed: ' + e.message } }];
}

const items = (candidates && candidates.items) || [];
if (items.length === 0) {
  return [{ json: { skipped: true, reason: 'no cold leads', checked_at: new Date().toISOString() } }];
}

const results = { closed: [], errors: [], total: items.length };

for (const row of items) {
  try {
    const ctx = row.context_json || {};
    const newContext = { ...ctx, closed_reason: 'cold_no_response', closed_at: new Date().toISOString() };
    await this.helpers.httpRequest({
      method: 'POST',
      url: ERP_BASE + '/api/internal/wa-state',
      headers: { 'X-Internal-Token': AUDIT_TOKEN, 'Content-Type': 'application/json' },
      body: {
        phone_lead: row.phone_lead,
        state: 'closed',
        context_json: newContext,
        escalation_reason: 'closed_cold',
      },
      json: true,
      timeout: 10000,
    });
    results.closed.push({ phone: row.phone_lead, hours_silent: row.hours_silent });
  } catch (e) {
    results.errors.push({ phone: row.phone_lead, error: e.message });
  }
}

return [{ json: { ok: true, results, ran_at: new Date().toISOString() } }];
